#include <stdio.h>

#define MAX 505

typedef struct {
    int r, c;
} Point;

char grid[MAX][MAX];
Point queue[MAX * MAX];

int main() {
    int n, m;
    if (scanf("%d %d", &n, &m) != 2) return 0;

    int head = 0, tail = 0;

    for (int i = 0; i < n; i++) {
        scanf("%s", grid[i]);
        for (int j = 0; j < m; j++) {
            if (grid[i][j] == 'o') {
                queue[tail++] = (Point){i, j};
            }
        }
    }

    while (head < tail) {
        Point p = queue[head++];
        int r = p.r;
        int c = p.c;

        // A água cai para baixo se a posição abaixo for '.'
        if (r + 1 < n && grid[r + 1][c] == '.') {
            grid[r + 1][c] = 'o';
            queue[tail++] = (Point){r + 1, c};
        }

        // Se abaixo houver uma prateleira '#', a água escorre para a esquerda e para a direita
        if (r + 1 < n && grid[r + 1][c] == '#') {
            if (c - 1 >= 0 && grid[r][c - 1] == '.') {
                grid[r][c - 1] = 'o';
                queue[tail++] = (Point){r, c - 1};
            }
            if (c + 1 < m && grid[r][c + 1] == '.') {
                grid[r][c + 1] = 'o';
                queue[tail++] = (Point){r, c + 1};
            }
        }
    }

    for (int i = 0; i < n; i++) {
        puts(grid[i]);
    }

    return 0;
}
